const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length === 0 || input[0] === '') return;

    const n = parseInt(input[0], 10);
    let minCost = Infinity;

    let ptr = 1;
    for (let i = 0; i < n; i++) {
        const p = parseFloat(input[ptr++]);
        const g = parseFloat(input[ptr++]);
        const costFor1000g = (p / g) * 1000;
        if (costFor1000g < minCost) {
            minCost = costFor1000g;
        }
    }

    console.log(minCost.toFixed(2));
}

main();
